package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.annotation.JsonRawValue;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlProperty;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlRootElement;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlText;
import org.junit.Test;

import static org.junit.Assert.*;

public class ToXmlGeneratorRawValueWithJacksonXmlTextTest {

    @JacksonXmlRootElement(localName = "test-pojo")
    public static class TestPojo {
        @JacksonXmlProperty(isAttribute = true)
        public String id;

        @JacksonXmlText
        @JsonRawValue
        public String value;
    }

    @Test
    public void testWriteRawValueWithJacksonXmlText() throws Exception {
        XmlMapper xmlMapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "123";
        pojo.value = "<a>A</a><b someAttribute=\"B\">B</b>";

        String xml = xmlMapper.writeValueAsString(pojo);

        // Expected: raw XML content should be injected directly without wrapper element
        // The attribute id should be present, and the raw value should appear as direct child elements
        assertTrue(xml.contains("id=\"123\""));
        assertTrue(xml.contains("<a>A</a>"));
        assertTrue(xml.contains("<b someAttribute=\"B\">B</b>"));
        // Ensure there is no wrapper element like <value> around the raw content
        assertFalse(xml.contains("<value>"));
        assertFalse(xml.contains("</value>"));
    }

    @Test
    public void testWriteRawValueWithJacksonXmlTextAndEmptyValue() throws Exception {
        XmlMapper xmlMapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "456";
        pojo.value = "";

        String xml = xmlMapper.writeValueAsString(pojo);

        // Should still produce valid XML without wrapper element
        assertTrue(xml.contains("id=\"456\""));
        // No extra wrapper element
        assertFalse(xml.contains("<value>"));
        assertFalse(xml.contains("</value>"));
    }

    @Test
    public void testWriteRawValueWithJacksonXmlTextAndNullValue() throws Exception {
        XmlMapper xmlMapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "789";
        pojo.value = null;

        String xml = xmlMapper.writeValueAsString(pojo);

        // With null raw value, the field should be omitted (since it's raw and null)
        // Only the attribute should remain
        assertTrue(xml.contains("id=\"789\""));
        // No wrapper element
        assertFalse(xml.contains("<value>"));
        assertFalse(xml.contains("</value>"));
    }

    @Test
    public void testWriteRawValueWithJacksonXmlTextAndComplexNestedXml() throws Exception {
        XmlMapper xmlMapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "complex";
        pojo.value = "<nested><child attr=\"val\">text</child></nested>";

        String xml = xmlMapper.writeValueAsString(pojo);

        assertTrue(xml.contains("id=\"complex\""));
        assertTrue(xml.contains("<nested>"));
        assertTrue(xml.contains("<child attr=\"val\">text</child>"));
        assertFalse(xml.contains("<value>"));
        assertFalse(xml.contains("</value>"));
    }

    @Test
    public void testWriteRawValueWithoutJacksonXmlText() throws Exception {
        // This test ensures that without @JacksonXmlText, raw value is wrapped
        @JacksonXmlRootElement(localName = "test-pojo2")
        class TestPojo2 {
            @JacksonXmlProperty(isAttribute = true)
            public String id;

            @JsonRawValue  // No @JacksonXmlText
            public String value;
        }

        XmlMapper xmlMapper = new XmlMapper();
        TestPojo2 pojo = new TestPojo2();
        pojo.id = "123";
        pojo.value = "<a>A</a>";

        String xml = xmlMapper.writeValueAsString(pojo);

        // Should have wrapper element <value>
        assertTrue(xml.contains("<value>"));
        assertTrue(xml.contains("</value>"));
        assertTrue(xml.contains("<a>A</a>"));
    }
}

