        @JsonRawValue
        public String value;
    }

    @Test
    public void testWriteRawValueWithJacksonXmlText() throws Exception {
        XmlMapper xmlMapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "123";
        pojo.value = "<a>A</a><b someAttribute=\"B\">B</b>";

        String xml = xmlMapper.writeValueAsString(pojo);

        // Expected: raw XML content should be injected directly without wrapper element
        String expected = "<test-pojo id=\"123\"><a>A</a><b someAttribute=\"B\">B</b></test-pojo>";
        assertEquals(expected, xml);
    }

    @Test
    public void testWriteRawValueWithOffsetAndJacksonXmlText() throws Exception {
        // Custom serializer to test writeRawValue with offset/length
        @JacksonXmlRootElement(localName = "test-pojo")
        class OffsetPojo {
            @JacksonXmlProperty(isAttribute = true)
            public String id;

            @JacksonXmlText
            @JsonSerialize(using = OffsetSerializer.class)
            public String value;
        }

        XmlMapper xmlMapper = new XmlMapper();
        OffsetPojo pojo = new OffsetPojo();
        pojo.id = "offset";
        pojo.value = "PREFIX<raw>content</raw>SUFFIX";

        String xml = xmlMapper.writeValueAsString(pojo);

        // Expect only the substring between PREFIX and SUFFIX
        String expected = "<test-pojo id=\"offset\"><raw>content</raw></test-pojo>";
        assertEquals(expected, xml);
    }

    static class OffsetSerializer extends JsonSerializer<String> {
        @Override
        public void serialize(String value, JsonGenerator gen, SerializerProvider provider) throws IOException {
            // Write substring (skip 6 chars from start, take content without 6-char suffix)
            gen.writeRawValue(value, 6, value.length() - 12);
        }
    }

    @Test
    public void testWriteRawValueWithCharArrayAndJacksonXmlText() throws Exception {
        // Custom serializer to test char[] writing
        @JacksonXmlRootElement(localName = "test-pojo")
        class CharsPojo {
            @JacksonXmlProperty(isAttribute = true)
            public String id;

            @JacksonXmlText
            @JsonSerialize(using = CharsSerializer.class)
            public String value;
        }

        XmlMapper xmlMapper = new XmlMapper();
        CharsPojo pojo = new CharsPojo();
        pojo.id = "chars";
        pojo.value = "PREFIX<chars>content</chars>SUFFIX";

        String xml = xmlMapper.writeValueAsString(pojo);

        // Expect only the middle part of the content
        String expected = "<test-pojo id=\"chars\"><chars>content</chars></test-pojo>";
        assertEquals(expected, xml);
    }

    static class CharsSerializer extends JsonSerializer<String> {
        @Override
        public void serialize(String value, JsonGenerator gen, SerializerProvider provider) throws IOException {
            // Convert to char[] and write subset
            char[] chars = value.toCharArray();
            // Skip "PREFIX" (6 chars) and take content without "SUFFIX" (6 chars)
            gen.writeRawValue(chars, 6, chars.length - 12);
        }
    }

    @Test
    public void testWriteRawValueWithoutJacksonXmlText() throws Exception {
        // Test that without @JacksonXmlText, raw value is wrapped
        @JacksonXmlRootElement(localName = "wrapper")
        class WrappedPojo {
            @JacksonXmlProperty(isAttribute = true)
            public String id;

            @JsonRawValue  // No @JacksonXmlText
            public String value;
        }

        XmlMapper xmlMapper = new XmlMapper();
        WrappedPojo pojo = new WrappedPojo();
        pojo.id = "789";
        pojo.value = "<x>X</x><y>Y</y>";

        String xml = xmlMapper.writeValueAsString(pojo);

        // Without @JacksonXmlText, raw value should be wrapped in element named after field
        String expected = "<wrapper id=\"789\"><value><x>X</x><y>Y</y></value></wrapper>";
        assertEquals(expected, xml);
    }

    @Test
    public void testWriteRawValueWithEmptyContent() throws Exception {
        XmlMapper xmlMapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "empty";
        pojo.value = "";

        String xml = xmlMapper.writeValueAsString(pojo);

        String expected = "<test-pojo id=\"empty\"></test-pojo>";
        assertEquals(expected, xml);
    }

    @Test
    public void testWriteRawValueWithSpecialCharacters() throws Exception {
        XmlMapper xmlMapper = new XmlMapper();
        TestPojo pojo = new TestPojo();
        pojo.id = "special";
        pojo.value = "<tag>&amp;&lt;&gt;</tag>";

        String xml = xmlMapper.writeValueAsString(pojo);

        // The raw XML should be written as-is (not double-escaped)
        String expected = "<test-pojo id=\"special\"><tag>&amp;&lt;&gt;</tag></test-pojo>";
        assertEquals(expected, xml);
    }
}

