package com.fasterxml.jackson.dataformat.xml;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JsonAppend;
import com.fasterxml.jackson.databind.annotation.JsonAppend.Prop;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.ser.VirtualBeanPropertyWriter;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlRootElement;
import org.junit.Test;

import java.io.IOException;

import static org.junit.Assert.*;

public class JacksonXmlAnnotationIntrospectorTest {

    @JacksonXmlRootElement(localName = "Pojo")
    @JsonAppend(
        props = { @Prop(name = "virtual", value = SimpleVirtualPropertyWriter.class) }
    )
    public static class Pojo {
        private String name;

        public Pojo() { }

        public Pojo(String name) {
            this.name = name;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }
    }

    public static class SimpleVirtualPropertyWriter extends VirtualBeanPropertyWriter {
        protected SimpleVirtualPropertyWriter() { }

        protected SimpleVirtualPropertyWriter(BeanPropertyDefinition propDef, Annotations annotations,
                JavaType declaredType) {
            super(propDef, annotations, declaredType);
        }

        @Override
        protected Object value(Object bean, JsonGenerator gen, SerializerProvider prov) throws IOException {
            return "bar";
        }

        @Override
        public VirtualBeanPropertyWriter withConfig(MapperConfig<?> config, AnnotatedClass declaringClass,
                BeanPropertyDefinition propDef, JavaType type) {
            return new SimpleVirtualPropertyWriter(propDef, null, type);
        }
    }

    @Test
    public void testVirtualPropertyNotDuplicated() throws JsonProcessingException {
        XmlMapper mapper = new XmlMapper();
        Pojo pojo = new Pojo("foo");
        String xml = mapper.writeValueAsString(pojo);

        // Count occurrences of "<virtual>"
        int count = countSubstring(xml, "<virtual>");
        assertEquals("Virtual property should appear exactly once", 1, count);

        // Also verify the structure
        assertTrue(xml.contains("<name>foo</name>"));
        assertTrue(xml.contains("<virtual>bar</virtual>"));

        // Ensure no duplicate closing tags
        int closingCount = countSubstring(xml, "</virtual>");
        assertEquals("Closing tag for virtual should appear exactly once", 1, closingCount);
    }

    private int countSubstring(String str, String sub) {
        int count = 0;
        int idx = 0;
        while ((idx = str.indexOf(sub, idx)) != -1) {
            count++;
            idx += sub.length();
        }
        return count;
    }
}

