package com.fasterxml.jackson.dataformat.xml.ser;

import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.fasterxml.jackson.dataformat.xml.XmlTestBase;
import com.fasterxml.jackson.dataformat.xml.annotation.JacksonXmlProperty;
import org.junit.Test;

import java.io.StringWriter;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ToXmlGeneratorInfinityTest extends XmlTestBase {

    // Test that when WRITE_XML_SCHEMA_CONFORMING_FLOATS is enabled,
    // positive infinity for double is serialized as "INF"
    @Test
    public void testPositiveInfinityDoubleEnabled() throws Exception {
        XmlMapper mapper = XmlMapper.builder()
                .enable(ToXmlGenerator.Feature.WRITE_XML_SCHEMA_CONFORMING_FLOATS)
                .build();
        StringWriter sw = new StringWriter();
        mapper.writeValue(sw, new DoubleWrapper(Double.POSITIVE_INFINITY));
        String xml = sw.toString();
        assertTrue(xml.contains(">INF<"));
    }

    // Test that when WRITE_XML_SCHEMA_CONFORMING_FLOATS is enabled,
    // negative infinity for double is serialized as "-INF"
    @Test
    public void testNegativeInfinityDoubleEnabled() throws Exception {
        XmlMapper mapper = XmlMapper.builder()
                .enable(ToXmlGenerator.Feature.WRITE_XML_SCHEMA_CONFORMING_FLOATS)
                .build();
        StringWriter sw = new StringWriter();
        mapper.writeValue(sw, new DoubleWrapper(Double.NEGATIVE_INFINITY));
        String xml = sw.toString();
        assertTrue(xml.contains(">-INF<"));
    }

    // Test that when WRITE_XML_SCHEMA_CONFORMING_FLOATS is enabled,
    // positive infinity for float is serialized as "INF"
    @Test
    public void testPositiveInfinityFloatEnabled() throws Exception {
        XmlMapper mapper = XmlMapper.builder()
                .enable(ToXmlGenerator.Feature.WRITE_XML_SCHEMA_CONFORMING_FLOATS)
                .build();
        StringWriter sw = new StringWriter();
        mapper.writeValue(sw, new FloatWrapper(Float.POSITIVE_INFINITY));
        String xml = sw.toString();
        assertTrue(xml.contains(">INF<"));
    }

