    // negative infinity for float is serialized as "-INF"
    @Test
    public void testNegativeInfinityFloatEnabled() throws Exception {
        XmlMapper mapper = XmlMapper.builder()
                .enable(ToXmlGenerator.Feature.WRITE_XML_SCHEMA_CONFORMING_FLOATS)
                .build();
        StringWriter sw = new StringWriter();
        mapper.writeValue(sw, new FloatWrapper(Float.NEGATIVE_INFINITY));
        String xml = sw.toString();
        assertTrue(xml.contains(">-INF<"));
    }

    // Test that when WRITE_XML_SCHEMA_CONFORMING_FLOATS is disabled (default),
    // positive infinity for double is serialized as "Infinity"
    @Test
    public void testPositiveInfinityDoubleDisabled() throws Exception {
        XmlMapper mapper = XmlMapper.builder()
                .disable(ToXmlGenerator.Feature.WRITE_XML_SCHEMA_CONFORMING_FLOATS)
                .build();
        StringWriter sw = new StringWriter();
        mapper.writeValue(sw, new DoubleWrapper(Double.POSITIVE_INFINITY));
        String xml = sw.toString();
        assertTrue(xml.contains(">Infinity<"));
    }

