    @Test
    public void testNegativeInfinityDoubleDisabled() throws Exception {
        XmlMapper mapper = XmlMapper.builder()
                .disable(ToXmlGenerator.Feature.WRITE_XML_SCHEMA_CONFORMING_FLOATS)
                .build();
        StringWriter sw = new StringWriter();
        mapper.writeValue(sw, new DoubleWrapper(Double.NEGATIVE_INFINITY));
        String xml = sw.toString();
        assertTrue(xml.contains(">-Infinity<"));
    }

    // Test that when WRITE_XML_SCHEMA_CONFORMING_FLOATS is disabled (default),
    // positive infinity for float is serialized as "Infinity"
    @Test
    public void testPositiveInfinityFloatDisabled() throws Exception {
        XmlMapper mapper = XmlMapper.builder()
                .disable(ToXmlGenerator.Feature.WRITE_XML_SCHEMA_CONFORMING_FLOATS)
                .build();
        StringWriter sw = new StringWriter();
